insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000001', E'cs-prob-ollama', E'Running open LLMs locally is too complex for everyday developers', E'If unsolved, builders stay stuck on cloud APIs—losing privacy, paying per token, and failing offline demos—while local model tooling remains fragmented.', E'If unsolved, builders stay stuck on cloud APIs—losing privacy, paying per token, and failing offline demos—while local model tooling remains fragmented.\n\n## Ollama\n\n**Ollama revolutionized the local AI movement, making running open LLMs as simple as Docker.**\n\nDevelopers bundle, customize, and run models like Llama 3, Mistral, and DeepSeek locally with hardware GPU acceleration and an OpenAI-compatible REST API, serving as the foundational local runtime for countless hackathon innovations.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
insert into public.ideas (id, slug, title, summary, thesis, solution, target_users, status, research_status, origin, reviewed_by_human, created_by) values (E'40000000-0000-4000-9000-000000000001', E'cs-idea-ollama', E'Ollama', E'Get up and running with large language models locally on macOS, Linux, and Windows.', E'Ollama packages local LLM runtimes like Docker: pull a model, run it with GPU acceleration, and serve an OpenAI-compatible API on your machine.', E'## Ollama\n\n**Ollama revolutionized the local AI movement, making running open LLMs as simple as Docker.**\n\nDevelopers bundle, customize, and run models like Llama 3, Mistral, and DeepSeek locally with hardware GPU acceleration and an OpenAI-compatible REST API, serving as the foundational local runtime for countless hackathon innovations.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'published', 'verified', 'imported', true, E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
