insert into public.previous_attempts (id, idea_id, name, description, outcome, lesson, source_url) values (E'41000000-0000-4000-9000-000000000001', E'40000000-0000-4000-9000-000000000001', E'Ollama Reference Build', E'Key signals: ~180k★; $88M total; $65M; ~9M MAU; $88M Docker Desktop founders (Morgan/Chiang); ''Docker for local LLMs''.', E'active', E'Make the hard thing feel like Docker: ruthless DX packaging can turn research models into a default local runtime and a venture-scale business.', E'https://github.com/ollama/ollama') on conflict (id) do nothing;
insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000002', E'cs-prob-1inch-network', E'DEX traders lose value to poor routing, slippage, and MEV', E'Without smart aggregation, swappers pay excess slippage and gas across fragmented liquidity pools and remain exposed to front-running.', E'Without smart aggregation, swappers pay excess slippage and gas across fragmented liquidity pools and remain exposed to front-running.\n\n## 1inch Network\n\n**1inch was famously created during the ETHNewYork Hackathon in 2019 and grew into a multi-billion dollar DeFi cornerstone.**\n\n1inch splits swap orders across dozens of decentralized liquidity pools in a single transaction, finding the lowest slippage and gas costs while protecting traders from front-running MEV attacks.', array[E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
insert into public.ideas (id, slug, title, summary, thesis, solution, target_users, status, research_status, origin, reviewed_by_human, created_by) values (E'40000000-0000-4000-9000-000000000002', E'cs-idea-1inch-network', E'1inch Network', E'Decentralized exchange aggregator optimizing token swap routes and shielding against slippage.', E'1inch splits orders across many liquidity sources in one transaction to minimize slippage and improve execution quality for traders.', E'## 1inch Network\n\n**1inch was famously created during the ETHNewYork Hackathon in 2019 and grew into a multi-billion dollar DeFi cornerstone.**\n\n1inch splits swap orders across dozens of decentralized liquidity pools in a single transaction, finding the lowest slippage and gas costs while protecting traders from front-running MEV attacks.', array[E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'published', 'verified', 'imported', true, E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
