insert into public.previous_attempts (id, idea_id, name, description, outcome, lesson, source_url) values (E'41000000-0000-4000-9000-000000000002', E'40000000-0000-4000-9000-000000000002', E'1inch Network Reference Build', E'Key signals: $190M raised; $2.25B val.; $813B; $190M; $2.25B; $813B+ volume Textbook hackathon→unicorn: ETHNewYork/ETHGlobal 2019 → $190M raised, peak ~$2.25B val.', E'active', E'A weekend hackathon DEX aggregator can become category infrastructure when it obsessively optimizes a daily pain (slippage, routing, MEV) and keeps shipping across chains.', E'https://github.com/1inch') on conflict (id) do nothing;
insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000003', E'cs-prob-supabase-platform', E'Lack of open, self-hostable Firebase alternative with PostgreSQL database, auth, and edge functions', E'If unsolved, the status quo keeps hurting users: supabase Started as an ambitious open-source developer project, Supabase is now the backbone of modern web dev. Provides a dedicated PostgreSQL database, instant REST and GraphQL APIs, real-time WebSocket subscriptions, built-in row-level security authentication, and sto', E'If unsolved, the status quo keeps hurting users: supabase Started as an ambitious open-source developer project, Supabase is now the backbone of modern web dev. Provides a dedicated PostgreSQL database, instant REST and GraphQL APIs, real-time WebSocket subscriptions, built-in row-level security authentication, and sto\n\n## Supabase\n\n**Started as an ambitious open-source developer project, Supabase is now the backbone of modern web dev.**\n\nProvides a dedicated PostgreSQL database, instant REST and GraphQL APIs, real-time WebSocket subscriptions, built-in row-level security authentication, and storage buckets out of the box.', array[E'full-stack developers', E'platform engineering teams', E'startup CTOs', E'DevOps engineers'], 'medium', 'published', 'verified', 'imported', true, E'Technology & DevTools', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
