insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000004', E'cs-prob-li-fi-aggregator', E'Users lack a reliable way to: multi-chain liquidity routing protocol and cross-chain bridge aggregation API', E'If unsolved, the status quo keeps hurting users: lI.FI Winner @ ETHGlobal Hackathons, LI.FI is the ultimate multi-chain liquidity aggregation layer. LI.FI aggregates bridges (Stargate, Hop, Across) and decentralized exchanges across 20+ blockchains, allowing developers to embed 1-click cross-chain swaps directly into a', E'If unsolved, the status quo keeps hurting users: lI.FI Winner @ ETHGlobal Hackathons, LI.FI is the ultimate multi-chain liquidity aggregation layer. LI.FI aggregates bridges (Stargate, Hop, Across) and decentralized exchanges across 20+ blockchains, allowing developers to embed 1-click cross-chain swaps directly into a\n\n## LI.FI\n\n**Winner @ ETHGlobal Hackathons, LI.FI is the ultimate multi-chain liquidity aggregation layer.**\n\nLI.FI aggregates bridges (Stargate, Hop, Across) and decentralized exchanges across 20+ blockchains, allowing developers to embed 1-click cross-chain swaps directly into any dApp.', array[E'smart-contract developers', E'dApp product teams', E'DAO operators', E'wallet users'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
