insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000005', E'cs-prob-posthog-analytics', E'Lack of open, self-hostable product , session replays, feature flags, and A/B testing suite', E'If unsolved, the status quo keeps hurting users: postHog Born in open-source hackathons, PostHog is the all-in-one developer platform for product analytics. Engineers self-host or use cloud PostHog to analyze user funnels, watch full session screen recordings, execute feature flag rollouts, and run scientific A/B tests', E'If unsolved, the status quo keeps hurting users: postHog Born in open-source hackathons, PostHog is the all-in-one developer platform for product analytics. Engineers self-host or use cloud PostHog to analyze user funnels, watch full session screen recordings, execute feature flag rollouts, and run scientific A/B tests\n\n## PostHog\n\n**Born in open-source hackathons, PostHog is the all-in-one developer platform for product analytics.**\n\nEngineers self-host or use cloud PostHog to analyze user funnels, watch full session screen recordings, execute feature flag rollouts, and run scientific A/B tests with complete data privacy.', array[E'full-stack developers', E'platform engineering teams', E'startup CTOs', E'DevOps engineers'], 'medium', 'published', 'verified', 'imported', true, E'Technology & DevTools', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
