insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000006', E'cs-prob-meilisearch-engine', E'Search experiences are slow and hard to tune: typo-tolerant search designed for delightful search experiences', E'If unsolved, the status quo keeps hurting users: meilisearch Meilisearch is a Rust-powered search engine built to deliver sub-50ms search experiences. Features instant typo tolerance, filters, faceted search, and multi-language support out of the box with zero complex Lucene tuning required.', E'If unsolved, the status quo keeps hurting users: meilisearch Meilisearch is a Rust-powered search engine built to deliver sub-50ms search experiences. Features instant typo tolerance, filters, faceted search, and multi-language support out of the box with zero complex Lucene tuning required.\n\n## Meilisearch\n\n**Meilisearch is a Rust-powered search engine built to deliver sub-50ms search experiences.**\n\nFeatures instant typo tolerance, filters, faceted search, and multi-language support out of the box with zero complex Lucene tuning required.', array[E'full-stack developers', E'platform engineering teams', E'startup CTOs', E'DevOps engineers'], 'medium', 'published', 'verified', 'imported', true, E'Technology & DevTools', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
