insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000007', E'cs-prob-element-matrix', E'Organizations lack sovereign, end-to-end encrypted collaboration outside Big Tech silos', E'Without open protocol-based messaging, governments and high-trust teams remain locked into proprietary chat stacks with weak data sovereignty.', E'Without open protocol-based messaging, governments and high-trust teams remain locked into proprietary chat stacks with weak data sovereignty.\n\n## Element (Matrix)\n\n**Element is an open-source secure collaboration client providing sovereign decentralized messaging.**\n\nBuilt on the open Matrix standard, Element provides end-to-end encrypted group chats, voice calls, and file transfers, adopted by the French and German governments for national public sector communications.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
