insert into public.previous_attempts (id, idea_id, name, description, outcome, lesson, source_url) values (E'41000000-0000-4000-9000-000000000007', E'40000000-0000-4000-9000-000000000007', E'Element (Matrix) Reference Build', E'Key signals: ~13k★ Element — flagship Matrix client (E2EE chat/calls/files; sovereign collaboration).', E'active', E'Sovereign collaboration wins when you own the open protocol layer (Matrix) and prove deployments in high-trust environments—not when you chase social-app vanity metrics.', E'https://github.com/element-hq') on conflict (id) do nothing;
insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000008', E'cs-prob-screenpipe-ai', E'Personal AI agents lack continuous local context', E'If unsolved, the status quo keeps hurting users: screenpipe AI Born as a hackathon sensation, Screenpipe is an open-source library that captures 24/7 desktop screen and microphone context locally. Operating 100% on-device with zero data leaving the user''s computer, Screenpipe runs background OCR and Whisper audio trans', E'If unsolved, the status quo keeps hurting users: screenpipe AI Born as a hackathon sensation, Screenpipe is an open-source library that captures 24/7 desktop screen and microphone context locally. Operating 100% on-device with zero data leaving the user''s computer, Screenpipe runs background OCR and Whisper audio trans\n\n## Screenpipe AI\n\n**Born as a hackathon sensation, Screenpipe is an open-source library that captures 24/7 desktop screen and microphone context locally.**\n\nOperating 100% on-device with zero data leaving the user''s computer, Screenpipe runs background OCR and Whisper audio transcription, creating a searchable local SQLite memory database.\n\nAI coding agents and personal assistants connect to Screenpipe via local APIs to understand exactly what the user is working on, automating repetitive workflow tasks, meeting minutes, and context retrieval without invading privacy.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
