insert into public.previous_attempts (id, idea_id, name, description, outcome, lesson, source_url) values (E'41000000-0000-4000-9000-000000000008', E'40000000-0000-4000-9000-000000000008', E'Screenpipe AI Reference Build', E'Key signals: ~21k★ YC S26; ~21k★; local-first screen/audio memory for agents.', E'active', E'Correct the origin myth: Screenpipe AI succeeded through sustained product and community work—builders should copy compounding craft, not fictional hackathon lore.', E'https://github.com/screenpipe/screenpipe') on conflict (id) do nothing;
