insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000010', E'cs-prob-openhands-opendevin', E'Software engineering tasks still need costly human babysitting', E'If unsolved, the status quo keeps hurting users: openHands OpenHands is an open-source autonomous AI software developer built by a global community of AI researchers. Operating in a secure Docker sandbox, OpenHands reads GitHub issues, writes code, runs terminal bash commands, executes browser tests, and resolves pull ', E'If unsolved, the status quo keeps hurting users: openHands OpenHands is an open-source autonomous AI software developer built by a global community of AI researchers. Operating in a secure Docker sandbox, OpenHands reads GitHub issues, writes code, runs terminal bash commands, executes browser tests, and resolves pull \n\n## OpenHands\n\n**OpenHands is an open-source autonomous AI software developer built by a global community of AI researchers.**\n\nOperating in a secure Docker sandbox, OpenHands reads GitHub issues, writes code, runs terminal bash commands, executes browser tests, and resolves pull requests autonomously, rivaling proprietary AI coding agents.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
