insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000011', E'cs-prob-marinade-finance', E'Users lock capital without liquidity: liquid staking protocol and stake pool automator for the Solana ecosystem', E'If unsolved, the status quo keeps hurting users: marinade Finance Marinade won the Solana Season Hackathon and became the premier liquid staking standard on Solana. Users stake SOL and receive mSOL, earning staking yield while retaining liquidity to trade, lend, and borrow across DeFi, while Marinade''s algorithm delega', E'If unsolved, the status quo keeps hurting users: marinade Finance Marinade won the Solana Season Hackathon and became the premier liquid staking standard on Solana. Users stake SOL and receive mSOL, earning staking yield while retaining liquidity to trade, lend, and borrow across DeFi, while Marinade''s algorithm delega\n\n## Marinade Finance\n\n**Marinade won the Solana Season Hackathon and became the premier liquid staking standard on Solana.**\n\nUsers stake SOL and receive mSOL, earning staking yield while retaining liquidity to trade, lend, and borrow across DeFi, while Marinade''s algorithm delegates stake across 100+ high-performance validators.', array[E'Solana ecosystem builders', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
