insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000012', E'cs-prob-safe-gnosis-safe', E'Single-key wallets put DAO and institutional treasuries at catastrophic risk', E'If unsolved, organizations custody billions behind one private key—creating single points of failure for hacks, mistakes, and insider risk.', E'If unsolved, organizations custody billions behind one private key—creating single points of failure for hacks, mistakes, and insider risk.\n\n## Safe (formerly Gnosis Safe)\n\n**Born at ETHBerlin, Safe is the undisputed gold standard for smart contract asset custody in Web3.**\n\nSafe requires multiple approved signatures for transaction execution, supports programmable recovery modules, gas abstraction, and session keys for institutional DAOs, foundations, and high-net-worth individuals.', array[E'DAO multisig signers', E'smart-contract developers', E'dApp product teams', E'DAO operators', E'wallet users'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
