insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000013', E'cs-prob-squads-protocol', E'Teams lack safe shared custody for wallet and treasury infrastructure for Solana teams', E'If unsolved, the status quo keeps hurting users: squads Protocol Squads emerged from a Solana hackathon to secure over $10B+ in treasury and program authority. Squads provides multi-sig spending limits, team permission tiers, batch transaction signing, and automated program upgrade authority for over 90% of top Solana ', E'If unsolved, the status quo keeps hurting users: squads Protocol Squads emerged from a Solana hackathon to secure over $10B+ in treasury and program authority. Squads provides multi-sig spending limits, team permission tiers, batch transaction signing, and automated program upgrade authority for over 90% of top Solana \n\n## Squads Protocol\n\n**Squads emerged from a Solana hackathon to secure over $10B+ in treasury and program authority.**\n\nSquads provides multi-sig spending limits, team permission tiers, batch transaction signing, and automated program upgrade authority for over 90% of top Solana protocols.', array[E'DAO multisig signers', E'Solana ecosystem builders', E'smart-contract developers', E'dApp product teams', E'DAO operators'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
