insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000015', E'cs-prob-langflow', E'People struggle to get visual framework when they need it for multi-agent AI architecture, RAG workflows, and component', E'If unsolved, the status quo keeps hurting users: langflow Originally created during an AI hackathon, Langflow is a dynamic UI framework for multi-agent RAG pipelines. Langflow enables developers to assemble complex agentic behaviors, test prompt variations in real-time execution sandboxes, and export clean, production-', E'If unsolved, the status quo keeps hurting users: langflow Originally created during an AI hackathon, Langflow is a dynamic UI framework for multi-agent RAG pipelines. Langflow enables developers to assemble complex agentic behaviors, test prompt variations in real-time execution sandboxes, and export clean, production-\n\n## Langflow\n\n**Originally created during an AI hackathon, Langflow is a dynamic UI framework for multi-agent RAG pipelines.**\n\nLangflow enables developers to assemble complex agentic behaviors, test prompt variations in real-time execution sandboxes, and export clean, production-grade Python code or FastAPI endpoints with one click.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
insert into public.ideas (id, slug, title, summary, thesis, solution, target_users, status, research_status, origin, reviewed_by_human, created_by) values (E'40000000-0000-4000-9000-000000000015', E'cs-idea-langflow', E'Langflow', E'Visual framework for multi-agent AI architecture, RAG workflows, and component orchestration.', E'Langflow solves it with originally created during an AI hackathon, Langflow is a dynamic UI framework for multi-agent RAG pipelines.', E'## Langflow\n\n**Originally created during an AI hackathon, Langflow is a dynamic UI framework for multi-agent RAG pipelines.**\n\nLangflow enables developers to assemble complex agentic behaviors, test prompt variations in real-time execution sandboxes, and export clean, production-grade Python code or FastAPI endpoints with one click.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'published', 'verified', 'imported', true, E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
