insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000017', E'cs-prob-excalidraw-whiteboard', E'People struggle to get virtual collaborative with hand-drawn feel when they need it for architecture diagramm', E'If unsolved, the status quo keeps hurting users: excalidraw Excalidraw was born as a developer hackathon experiment and became an indispensable tool for technical education. Allows students, teachers, and engineering teams to sketch system architecture, mathematical diagrams, and brainstorming mindmaps collaboratively ', E'If unsolved, the status quo keeps hurting users: excalidraw Excalidraw was born as a developer hackathon experiment and became an indispensable tool for technical education. Allows students, teachers, and engineering teams to sketch system architecture, mathematical diagrams, and brainstorming mindmaps collaboratively \n\n## Excalidraw\n\n**Excalidraw was born as a developer hackathon experiment and became an indispensable tool for technical education.**\n\nAllows students, teachers, and engineering teams to sketch system architecture, mathematical diagrams, and brainstorming mindmaps collaboratively with an intuitive hand-drawn aesthetic.', array[E'K-12 and university students', E'students and teachers', E'university researchers', E'edtech builders', E'self-learners'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
insert into public.ideas (id, slug, title, summary, thesis, solution, target_users, status, research_status, origin, reviewed_by_human, created_by) values (E'40000000-0000-4000-9000-000000000017', E'cs-idea-excalidraw-whiteboard', E'Excalidraw Whiteboard', E'Virtual collaborative whiteboard with hand-drawn feel for architecture diagramming and teaching.', E'Excalidraw Whiteboard solves it with excalidraw was born as a developer hackathon experiment and became an indispensable tool for technical education.', E'## Excalidraw\n\n**Excalidraw was born as a developer hackathon experiment and became an indispensable tool for technical education.**\n\nAllows students, teachers, and engineering teams to sketch system architecture, mathematical diagrams, and brainstorming mindmaps collaboratively with an intuitive hand-drawn aesthetic.', array[E'K-12 and university students', E'students and teachers', E'university researchers', E'edtech builders', E'self-learners'], 'published', 'verified', 'imported', true, E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
