insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000018', E'cs-prob-gitcoin-grants', E'Centralized intermediaries dominate quadratic funding protocol financing open-source software and public goods', E'If unsolved, the status quo keeps hurting users: gitcoin Grants Gitcoin transformed civic tech and open-source public goods financing via Quadratic Funding. Using mathematical quadratic funding formulas, Gitcoin amplifies the impact of small grassroots community contributions, distributing over $60M+ in community grant', E'If unsolved, the status quo keeps hurting users: gitcoin Grants Gitcoin transformed civic tech and open-source public goods financing via Quadratic Funding. Using mathematical quadratic funding formulas, Gitcoin amplifies the impact of small grassroots community contributions, distributing over $60M+ in community grant\n\n## Gitcoin Grants\n\n**Gitcoin transformed civic tech and open-source public goods financing via Quadratic Funding.**\n\nUsing mathematical quadratic funding formulas, Gitcoin amplifies the impact of small grassroots community contributions, distributing over $60M+ in community grants to essential open-source tools and social initiatives.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
