insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000019', E'cs-prob-mattermost-team', E'Lack of open, self-hostable secure collaboration platform for mission-critical developer and defense s', E'If unsolved, the status quo keeps hurting users: mattermost Mattermost is an open-source enterprise messaging platform built for high-security environments. Offers self-hosted team chat, workflow orchestration (Playbooks), and developer task boards with strict compliance (SOC2, HIPAA) for aerospace, financial, and gove', E'If unsolved, the status quo keeps hurting users: mattermost Mattermost is an open-source enterprise messaging platform built for high-security environments. Offers self-hosted team chat, workflow orchestration (Playbooks), and developer task boards with strict compliance (SOC2, HIPAA) for aerospace, financial, and gove\n\n## Mattermost\n\n**Mattermost is an open-source enterprise messaging platform built for high-security environments.**\n\nOffers self-hosted team chat, workflow orchestration (Playbooks), and developer task boards with strict compliance (SOC2, HIPAA) for aerospace, financial, and government organizations.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
