insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000020', E'cs-prob-dify-ai', E'Lack of open, self-hostable LLM application development platform combining AI workflows, RAG, and agentic pipelines', E'If unsolved, the status quo keeps hurting users: dify.ai Dify is an enterprise-grade open-source LLM application development platform born from developer hackathons. Dify combines visual prompt engineering, contextual RAG indexing, tool integrations, and model monitoring in a single platform, enabling teams to deploy p', E'If unsolved, the status quo keeps hurting users: dify.ai Dify is an enterprise-grade open-source LLM application development platform born from developer hackathons. Dify combines visual prompt engineering, contextual RAG indexing, tool integrations, and model monitoring in a single platform, enabling teams to deploy p\n\n## Dify.ai\n\n**Dify is an enterprise-grade open-source LLM application development platform born from developer hackathons.**\n\nDify combines visual prompt engineering, contextual RAG indexing, tool integrations, and model monitoring in a single platform, enabling teams to deploy production AI agents and embeddable web chat assistants in minutes.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
