insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000024', E'cs-prob-affine-knowledge-os', E'Users lack a reliable way to: next-gen open-source collaborative base merging docs, whiteboards, and database', E'If unsolved, the status quo keeps hurting users: aFFiNE AFFiNE is an open-source workspace that bridges the gap between text notes and infinite visual whiteboards. Students switch seamlessly between linear written lecture summaries and freeform visual concept mapping on a single canvas, maintaining full data sovereignt', E'If unsolved, the status quo keeps hurting users: aFFiNE AFFiNE is an open-source workspace that bridges the gap between text notes and infinite visual whiteboards. Students switch seamlessly between linear written lecture summaries and freeform visual concept mapping on a single canvas, maintaining full data sovereignt\n\n## AFFiNE\n\n**AFFiNE is an open-source workspace that bridges the gap between text notes and infinite visual whiteboards.**\n\nStudents switch seamlessly between linear written lecture summaries and freeform visual concept mapping on a single canvas, maintaining full data sovereignty and local-first encryption.', array[E'K-12 and university students', E'students and teachers', E'university researchers', E'edtech builders', E'self-learners'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
