insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000025', E'cs-prob-jellyfin-media', E'Users lack a reliable way to: the volunteer-built open-source system putting users in complete control of digital', E'If unsolved, the status quo keeps hurting users: jellyfin Jellyfin is a completely free, open-source media server with zero tracking or premium paywalls. Enables community organizations and families to stream self-hosted movies, community audio archives, and television shows across smart TVs, mobile apps, and web brows', E'If unsolved, the status quo keeps hurting users: jellyfin Jellyfin is a completely free, open-source media server with zero tracking or premium paywalls. Enables community organizations and families to stream self-hosted movies, community audio archives, and television shows across smart TVs, mobile apps, and web brows\n\n## Jellyfin\n\n**Jellyfin is a completely free, open-source media server with zero tracking or premium paywalls.**\n\nEnables community organizations and families to stream self-hosted movies, community audio archives, and television shows across smart TVs, mobile apps, and web browsers with hardware transcoding.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
