insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000026', E'cs-prob-cow-protocol-cowswap', E'Retail traders lose value to MEV and slippage', E'If unsolved, the status quo keeps hurting users: coW Protocol Born out of Ethereum developer research, CoW Swap matches trades through decentralized batch auctions. Orders are matched peer-to-peer (Coincidence of Wants) and settled by competing off-chain solvers, guaranteeing maximum MEV protection, zero gas fees for f', E'If unsolved, the status quo keeps hurting users: coW Protocol Born out of Ethereum developer research, CoW Swap matches trades through decentralized batch auctions. Orders are matched peer-to-peer (Coincidence of Wants) and settled by competing off-chain solvers, guaranteeing maximum MEV protection, zero gas fees for f\n\n## CoW Protocol\n\n**Born out of Ethereum developer research, CoW Swap matches trades through decentralized batch auctions.**\n\nOrders are matched peer-to-peer (Coincidence of Wants) and settled by competing off-chain solvers, guaranteeing maximum MEV protection, zero gas fees for failed orders, and optimal execution prices.', array[E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
