insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000028', E'cs-prob-logseq-knowledge-graph', E'Users lack a reliable way to: privacy-first, open-source outliner and bi-directional management tool', E'If unsolved, the status quo keeps hurting users: logseq Logseq revolutionized personal knowledge management for university students and academics. Built on local Markdown and Org-mode plain text files, Logseq automatically establishes bi-directional backlinks, creates interactive graph views of interconnected study not', E'If unsolved, the status quo keeps hurting users: logseq Logseq revolutionized personal knowledge management for university students and academics. Built on local Markdown and Org-mode plain text files, Logseq automatically establishes bi-directional backlinks, creates interactive graph views of interconnected study not\n\n## Logseq\n\n**Logseq revolutionized personal knowledge management for university students and academics.**\n\nBuilt on local Markdown and Org-mode plain text files, Logseq automatically establishes bi-directional backlinks, creates interactive graph views of interconnected study notes, and integrates PDF annotation with flashcards.', array[E'K-12 and university students', E'students and teachers', E'university researchers', E'edtech builders', E'self-learners'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
