insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000029', E'cs-prob-decidim-democracy', E'Lack of open, self-hostable digital platform for citizen participation, participatory budgeting, and civic voting', E'If unsolved, the status quo keeps hurting users: decidim Decidim is the leading open-source platform for participatory democracy and civic governance. Used by Barcelona, Helsinki, and cities across Europe, Decidim enables municipal governments to run participatory budgeting, citizen assemblies, policy consultations, an', E'If unsolved, the status quo keeps hurting users: decidim Decidim is the leading open-source platform for participatory democracy and civic governance. Used by Barcelona, Helsinki, and cities across Europe, Decidim enables municipal governments to run participatory budgeting, citizen assemblies, policy consultations, an\n\n## Decidim\n\n**Decidim is the leading open-source platform for participatory democracy and civic governance.**\n\nUsed by Barcelona, Helsinki, and cities across Europe, Decidim enables municipal governments to run participatory budgeting, citizen assemblies, policy consultations, and public referendum voting with full transparency.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
