insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000030', E'cs-prob-xmtp-network', E'People struggle to get open protocol and developer when they need it for secure, encrypted wallet-to-wallet mess', E'If unsolved, the status quo keeps hurting users: xMTP Network Supported across major Web3 hackathons, XMTP is the open standard for decentralized messaging. XMTP delivers end-to-end encrypted messaging between Ethereum and Solana wallets, enabling social apps, customer support bots, and dApp notifications without centr', E'If unsolved, the status quo keeps hurting users: xMTP Network Supported across major Web3 hackathons, XMTP is the open standard for decentralized messaging. XMTP delivers end-to-end encrypted messaging between Ethereum and Solana wallets, enabling social apps, customer support bots, and dApp notifications without centr\n\n## XMTP Network\n\n**Supported across major Web3 hackathons, XMTP is the open standard for decentralized messaging.**\n\nXMTP delivers end-to-end encrypted messaging between Ethereum and Solana wallets, enabling social apps, customer support bots, and dApp notifications without centralized servers.', array[E'Solana ecosystem builders', E'smart-contract developers', E'dApp product teams', E'DAO operators', E'wallet users'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
