insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000031', E'cs-prob-organic-maps', E'Travelers lack privacy-focused open-source offline and turn-by-turn navigation for global travelers', E'If unsolved, the status quo keeps hurting users: organic Maps Organic Maps is a privacy-first, community-driven offline navigation app beloved by backpackers worldwide. Based on crowdsourced OpenStreetMap data, Organic Maps requires zero mobile data connection.', E'If unsolved, the status quo keeps hurting users: organic Maps Organic Maps is a privacy-first, community-driven offline navigation app beloved by backpackers worldwide. Based on crowdsourced OpenStreetMap data, Organic Maps requires zero mobile data connection.\n\n## Organic Maps\n\n**Organic Maps is a privacy-first, community-driven offline navigation app beloved by backpackers worldwide.**\n\nBased on crowdsourced OpenStreetMap data, Organic Maps requires zero mobile data connection. It offers 100% offline turn-by-turn driving, cycling, and hiking navigation with detailed mountain trails, elevation profiles, and zero ad tracking.', array[E'users in low-connectivity regions', E'backpackers and solo travelers', E'tour operators', E'privacy-conscious tourists', E'navigation app users'], 'medium', 'published', 'verified', 'imported', true, E'Travel & Tourism', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
insert into public.ideas (id, slug, title, summary, thesis, solution, target_users, status, research_status, origin, reviewed_by_human, created_by) values (E'40000000-0000-4000-9000-000000000031', E'cs-idea-organic-maps', E'Organic Maps', E'Fast, privacy-focused open-source offline maps and turn-by-turn navigation for global travelers.', E'Organic Maps solves it with privacy-first, community-driven offline navigation app beloved by backpackers worldwide.', E'## Organic Maps\n\n**Organic Maps is a privacy-first, community-driven offline navigation app beloved by backpackers worldwide.**\n\nBased on crowdsourced OpenStreetMap data, Organic Maps requires zero mobile data connection. It offers 100% offline turn-by-turn driving, cycling, and hiking navigation with detailed mountain trails, elevation profiles, and zero ad tracking.', array[E'users in low-connectivity regions', E'backpackers and solo travelers', E'tour operators', E'privacy-conscious tourists', E'navigation app users'], 'published', 'verified', 'imported', true, E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
