insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000033', E'cs-prob-kiwix-offline-knowledge', E'Lack of open, self-hostable reader bringing Wikipedia, medical guides, and textbooks to unserved areas', E'If unsolved, the status quo keeps hurting users: kiwix Kiwix provides offline access to humanity''s knowledge in areas without internet access. Compresses Wikipedia, Project Gutenberg, and Khan Academy into compact ZIM files that run on old computers and phones in schools, refugee camps, and developing regions without c', E'If unsolved, the status quo keeps hurting users: kiwix Kiwix provides offline access to humanity''s knowledge in areas without internet access. Compresses Wikipedia, Project Gutenberg, and Khan Academy into compact ZIM files that run on old computers and phones in schools, refugee camps, and developing regions without c\n\n## Kiwix\n\n**Kiwix provides offline access to humanity''s knowledge in areas without internet access.**\n\nCompresses Wikipedia, Project Gutenberg, and Khan Academy into compact ZIM files that run on old computers and phones in schools, refugee camps, and developing regions without cellular coverage.', array[E'K-12 and university students', E'users in low-connectivity regions', E'students and teachers', E'university researchers', E'edtech builders'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
