insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000035', E'cs-prob-qdrant-vector-engine', E'Users lack a reliable way to: high-performance, production-ready similarity search and embeddings database', E'If unsolved, the status quo keeps hurting users: qdrant Qdrant is an open-source vector similarity search engine and database written in Rust. Engineered for high-dimensional neural vector embeddings, Qdrant provides sub-millisecond filtering, payload-based metadata searching, and distributed clustering for production ', E'If unsolved, the status quo keeps hurting users: qdrant Qdrant is an open-source vector similarity search engine and database written in Rust. Engineered for high-dimensional neural vector embeddings, Qdrant provides sub-millisecond filtering, payload-based metadata searching, and distributed clustering for production \n\n## Qdrant\n\n**Qdrant is an open-source vector similarity search engine and database written in Rust.**\n\nEngineered for high-dimensional neural vector embeddings, Qdrant provides sub-millisecond filtering, payload-based metadata searching, and distributed clustering for production semantic search and RAG applications.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
