insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000036', E'cs-prob-openstreetmap-project', E'Lack of open, self-hostable global geographic database powering open navigation apps and humanitarian relief', E'If unsolved, the status quo keeps hurting users: openStreetMap The open-source ''Wikipedia of Maps'' that underpins modern independent navigation. Maintained by over 10 million volunteer mappers worldwide, OSM provides freely accessible geographical data on roads, hiking trails, transit stations, and local businesses, us', E'If unsolved, the status quo keeps hurting users: openStreetMap The open-source ''Wikipedia of Maps'' that underpins modern independent navigation. Maintained by over 10 million volunteer mappers worldwide, OSM provides freely accessible geographical data on roads, hiking trails, transit stations, and local businesses, us\n\n## OpenStreetMap\n\n**The open-source ''Wikipedia of Maps'' that underpins modern independent navigation.**\n\nMaintained by over 10 million volunteer mappers worldwide, OSM provides freely accessible geographical data on roads, hiking trails, transit stations, and local businesses, used extensively by disaster relief teams and travel developers.', array[E'backpackers and solo travelers', E'tour operators', E'privacy-conscious tourists', E'navigation app users'], 'medium', 'published', 'verified', 'imported', true, E'Travel & Tourism', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
