insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000037', E'cs-prob-twenty-crm', E'Legacy tools fail at open-source CRM platform providing full control over customer data and sales pipelines', E'If unsolved, the status quo keeps hurting users: twenty CRM Twenty is the modern open-source alternative to Salesforce and HubSpot. Engineers customize objects, automate sales pipelines, sync company email inboxes, and maintain total ownership of customer relationships without vendor lock-in.', E'If unsolved, the status quo keeps hurting users: twenty CRM Twenty is the modern open-source alternative to Salesforce and HubSpot. Engineers customize objects, automate sales pipelines, sync company email inboxes, and maintain total ownership of customer relationships without vendor lock-in.\n\n## Twenty CRM\n\n**Twenty is the modern open-source alternative to Salesforce and HubSpot.**\n\nEngineers customize objects, automate sales pipelines, sync company email inboxes, and maintain total ownership of customer relationships without vendor lock-in.', array[E'SMB operators', E'sales teams', E'commerce developers', E'open-source founders'], 'medium', 'published', 'verified', 'imported', true, E'Economics & Commerce', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
