insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000038', E'cs-prob-open-food-facts', E'Consumers lack transparent data for database of global products, nutrition scores, and allergen alerts', E'If unsolved, the status quo keeps hurting users: open Food Facts The open-source Wikipedia of food products empowering consumer choices worldwide. Crowdsources ingredient lists, allergens, and Nutri-Scores for over 3 million food products globally, offering open APIs powering health apps and scientific nutritional stud', E'If unsolved, the status quo keeps hurting users: open Food Facts The open-source Wikipedia of food products empowering consumer choices worldwide. Crowdsources ingredient lists, allergens, and Nutri-Scores for over 3 million food products globally, offering open APIs powering health apps and scientific nutritional stud\n\n## Open Food Facts\n\n**The open-source Wikipedia of food products empowering consumer choices worldwide.**\n\nCrowdsources ingredient lists, allergens, and Nutri-Scores for over 3 million food products globally, offering open APIs powering health apps and scientific nutritional studies.', array[E'SMB operators', E'sales teams', E'commerce developers', E'open-source founders'], 'medium', 'published', 'verified', 'imported', true, E'Economics & Commerce', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
