insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000039', E'cs-prob-kolibri-learning', E'Lack of open, self-hostable offline educational platform and curriculum portal for low-resource schools', E'If unsolved, the status quo keeps hurting users: kolibri (Learning Equality) An open-source educational platform designed to provide digital learning in offline environments. Kolibri provides interactive science simulations, literacy exercises, and teacher diagnostic dashboards on local wireless networks without intern', E'If unsolved, the status quo keeps hurting users: kolibri (Learning Equality) An open-source educational platform designed to provide digital learning in offline environments. Kolibri provides interactive science simulations, literacy exercises, and teacher diagnostic dashboards on local wireless networks without intern\n\n## Kolibri (Learning Equality)\n\n**An open-source educational platform designed to provide digital learning in offline environments.**\n\nKolibri provides interactive science simulations, literacy exercises, and teacher diagnostic dashboards on local wireless networks without internet access, serving over 10 million learners in 200+ countries.', array[E'K-12 and university students', E'users in low-connectivity regions', E'students and teachers', E'university researchers', E'edtech builders'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
