insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000040', E'cs-prob-instadapp', E'People struggle to get deFi smart account middleware and debt refinancing portal when they need it for decentralized fin', E'If unsolved, the status quo keeps hurting users: instadapp Born at ETHIndia Hackathon, Instadapp became one of the largest decentralized asset management platforms. Using DeFi Smart Accounts (DSA), Instadapp allows users to bridge collateral, refinance loans, and switch positions between Compound, Aave, and MakerDAO in', E'If unsolved, the status quo keeps hurting users: instadapp Born at ETHIndia Hackathon, Instadapp became one of the largest decentralized asset management platforms. Using DeFi Smart Accounts (DSA), Instadapp allows users to bridge collateral, refinance loans, and switch positions between Compound, Aave, and MakerDAO in\n\n## Instadapp\n\n**Born at ETHIndia Hackathon, Instadapp became one of the largest decentralized asset management platforms.**\n\nUsing DeFi Smart Accounts (DSA), Instadapp allows users to bridge collateral, refinance loans, and switch positions between Compound, Aave, and MakerDAO in single atomic flash-loan transactions.', array[E'DAO multisig signers', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
