insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000042', E'cs-prob-ratex-protocol', E'Centralized intermediaries dominate interest rate swap exchange for leveraged yield trading on Solana', E'If unsolved, the status quo keeps hurting users: rateX Protocol Winner of 1st Prize in DeFi @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC). RateX introduces synthetic fixed-income trading instruments to Solana.', E'If unsolved, the status quo keeps hurting users: rateX Protocol Winner of 1st Prize in DeFi @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC). RateX introduces synthetic fixed-income trading instruments to Solana.\n\n## RateX Protocol\n\n**Winner of 1st Prize in DeFi @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC).**\n\nRateX introduces synthetic fixed-income trading instruments to Solana. Traders lock in fixed yield rates or speculate on variable APY shifts with up to 10x leverage across kamino, marginfi, and staking pools.', array[E'Solana ecosystem builders', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
