insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000046', E'cs-prob-cal-com-scheduler', E'Lack of open, self-hostable scheduling infrastructure and customizable booking marketplace for teams', E'If unsolved, the status quo keeps hurting users: cal.com Cal.com (formerly Calendso) started in open source and became the global infrastructure for scheduling. Enables individuals, telehealth networks, and sales teams to schedule meetings, process payments via Stripe, and embed white-label booking widgets directly int', E'If unsolved, the status quo keeps hurting users: cal.com Cal.com (formerly Calendso) started in open source and became the global infrastructure for scheduling. Enables individuals, telehealth networks, and sales teams to schedule meetings, process payments via Stripe, and embed white-label booking widgets directly int\n\n## Cal.com\n\n**Cal.com (formerly Calendso) started in open source and became the global infrastructure for scheduling.**\n\nEnables individuals, telehealth networks, and sales teams to schedule meetings, process payments via Stripe, and embed white-label booking widgets directly into products.', array[E'SMB operators', E'sales teams', E'commerce developers', E'open-source founders'], 'medium', 'published', 'verified', 'imported', true, E'Economics & Commerce', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
