insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000049', E'cs-prob-plane-project-tracker', E'Lack of open, self-hostable extensible project management and issue tracking tool (alternative to Jira)', E'If unsolved, the status quo keeps hurting users: plane Plane is an open-source project management platform built for modern agile development teams. Features Kanban boards, sprint cycles, roadmap timelines, and real-time issue collaboration with integrations to GitHub, GitLab, and Slack.', E'If unsolved, the status quo keeps hurting users: plane Plane is an open-source project management platform built for modern agile development teams. Features Kanban boards, sprint cycles, roadmap timelines, and real-time issue collaboration with integrations to GitHub, GitLab, and Slack.\n\n## Plane\n\n**Plane is an open-source project management platform built for modern agile development teams.**\n\nFeatures Kanban boards, sprint cycles, roadmap timelines, and real-time issue collaboration with integrations to GitHub, GitLab, and Slack.', array[E'full-stack developers', E'platform engineering teams', E'startup CTOs', E'DevOps engineers'], 'medium', 'published', 'verified', 'imported', true, E'Technology & DevTools', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
