insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000050', E'cs-prob-documenso-signatures', E'Lack of open, self-hostable digital document signing platform and legally binding e-signature alternative', E'If unsolved, the status quo keeps hurting users: documenso Documenso is the community-driven open-source alternative to DocuSign. Enables individuals and enterprises to upload contracts, designate signature fields, verify signer identity with cryptographic hashing, and maintain audit trails with complete data sovereign', E'If unsolved, the status quo keeps hurting users: documenso Documenso is the community-driven open-source alternative to DocuSign. Enables individuals and enterprises to upload contracts, designate signature fields, verify signer identity with cryptographic hashing, and maintain audit trails with complete data sovereign\n\n## Documenso\n\n**Documenso is the community-driven open-source alternative to DocuSign.**\n\nEnables individuals and enterprises to upload contracts, designate signature fields, verify signer identity with cryptographic hashing, and maintain audit trails with complete data sovereignty.', array[E'SMB operators', E'sales teams', E'commerce developers', E'open-source founders'], 'medium', 'published', 'verified', 'imported', true, E'Economics & Commerce', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
