insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000051', E'cs-prob-flowise-ai', E'Non-specialists struggle to assemble production LLM agent pipelines', E'Without visual orchestration, teams waste weeks wiring LangChain components, and brittle demos never reach production—or get replaced by coding agents.', E'Without visual orchestration, teams waste weeks wiring LangChain components, and brittle demos never reach production—or get replaced by coding agents.\n\n## Flowise AI\n\n**Flowise is an open-source visual orchestration platform for building LLM agents, LangChain pipelines, and multi-modal assistants.**\n\nDevelopers and non-technical builders visually connect vector stores, embedding models, prompt templates, and custom API tools into production-ready agents.\n\nIncludes built-in support for streaming responses, chat widgets, webhook triggers, and enterprise authentication, making LLM application prototyping 10x faster.', array[E'AI engineers', E'indie hackers prototyping LLM apps', E'ML platform teams', E'open-source contributors'], 'medium', 'published', 'verified', 'imported', true, E'AI', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
