insert into public.previous_attempts (id, idea_id, name, description, outcome, lesson, source_url) values (E'41000000-0000-4000-9000-000000000051', E'40000000-0000-4000-9000-000000000051', E'Flowise AI Reference Build', E'YC S23 → Workday (Aug 2025) → EOL Aug 31, 2026 (repo archived).', E'sunset', E'Visual LLM builders can win YC and adoption yet still sunset when coding agents and acquirers change the category—plan for distribution and durability, not just demos.', E'https://github.com/FlowiseAI/Flowise') on conflict (id) do nothing;
insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000052', E'cs-prob-sablier-protocol', E'People struggle to get token vesting and programmatic token distribution infrastructure when they need it for Web3 proto', E'If unsolved, the status quo keeps hurting users: sablier Protocol Originated in an Ethereum hackathon, Sablier pioneered streaming token distribution for DAOs. Sablier enables organizations to lock tokens into smart streams that vest linearly or exponentially per second, guaranteeing team compliance, transparent vestin', E'If unsolved, the status quo keeps hurting users: sablier Protocol Originated in an Ethereum hackathon, Sablier pioneered streaming token distribution for DAOs. Sablier enables organizations to lock tokens into smart streams that vest linearly or exponentially per second, guaranteeing team compliance, transparent vestin\n\n## Sablier Protocol\n\n**Originated in an Ethereum hackathon, Sablier pioneered streaming token distribution for DAOs.**\n\nSablier enables organizations to lock tokens into smart streams that vest linearly or exponentially per second, guaranteeing team compliance, transparent vesting schedules, and unhackable token distributions.', array[E'DAO multisig signers', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
