insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000055', E'cs-prob-openemr-healthcare', E'Users lack a reliable way to: oNC-certified open-source electronic medical records and medical practice management platf', E'If unsolved, the status quo keeps hurting users: openEMR OpenEMR is the leading open-source electronic health records (EHR) and practice management system. Used by thousands of clinics globally, OpenEMR provides patient scheduling, electronic medical records, e-prescribing, medical billing, and secure patient portals w', E'If unsolved, the status quo keeps hurting users: openEMR OpenEMR is the leading open-source electronic health records (EHR) and practice management system. Used by thousands of clinics globally, OpenEMR provides patient scheduling, electronic medical records, e-prescribing, medical billing, and secure patient portals w\n\n## OpenEMR\n\n**OpenEMR is the leading open-source electronic health records (EHR) and practice management system.**\n\nUsed by thousands of clinics globally, OpenEMR provides patient scheduling, electronic medical records, e-prescribing, medical billing, and secure patient portals with multi-language support.', array[E'patients and caregivers', E'clinicians', E'healthtech builders', E'elderly-care families'], 'medium', 'published', 'verified', 'imported', true, E'Healthcare & Medtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
