insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000056', E'cs-prob-mango-markets', E'Centralized intermediaries dominate cross-margin trading, spot lending, and perpetual futures exchange on Solana', E'If unsolved, the status quo keeps hurting users: mango Markets Mango Markets was created in the Solana Wormhole Hackathon and set the benchmark for margin trading. Provides up to 10x leverage trading on spot and perpetual markets, automated margin borrowing, and liquid staking collateralization with near-zero transacti', E'If unsolved, the status quo keeps hurting users: mango Markets Mango Markets was created in the Solana Wormhole Hackathon and set the benchmark for margin trading. Provides up to 10x leverage trading on spot and perpetual markets, automated margin borrowing, and liquid staking collateralization with near-zero transacti\n\n## Mango Markets\n\n**Mango Markets was created in the Solana Wormhole Hackathon and set the benchmark for margin trading.**\n\nProvides up to 10x leverage trading on spot and perpetual markets, automated margin borrowing, and liquid staking collateralization with near-zero transaction fees.', array[E'Solana ecosystem builders', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
