insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000057', E'cs-prob-poap-proof-of-attendance', E'Users lack a reliable way to: cryptographic memory bookmarks preserving human life experiences as digital collectibles', E'If unsolved, the status quo keeps hurting users: pOAP Created at ETHDenver 2019, POAP became the global standard for event verification and attendance badges. Organizers distribute cryptographic badge tokens to physical and virtual event attendees, creating non-transferable digital memories and verifiable participation', E'If unsolved, the status quo keeps hurting users: pOAP Created at ETHDenver 2019, POAP became the global standard for event verification and attendance badges. Organizers distribute cryptographic badge tokens to physical and virtual event attendees, creating non-transferable digital memories and verifiable participation\n\n## POAP\n\n**Created at ETHDenver 2019, POAP became the global standard for event verification and attendance badges.**\n\nOrganizers distribute cryptographic badge tokens to physical and virtual event attendees, creating non-transferable digital memories and verifiable participation graphs for community governance.', array[E'smart-contract developers', E'dApp product teams', E'DAO operators', E'wallet users'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
