insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000058', E'cs-prob-formbricks-experience', E'Lack of open, self-hostable user survey suite and product feedback platform', E'If unsolved, the status quo keeps hurting users: formbricks Formbricks provides micro-surveys targeted inside web and mobile applications. Triggered by user actions or user segments, Formbricks gathers customer feedback, NPS scores, and churn insights directly into existing data pipelines without intrusive popups.', E'If unsolved, the status quo keeps hurting users: formbricks Formbricks provides micro-surveys targeted inside web and mobile applications. Triggered by user actions or user segments, Formbricks gathers customer feedback, NPS scores, and churn insights directly into existing data pipelines without intrusive popups.\n\n## Formbricks\n\n**Formbricks provides micro-surveys targeted inside web and mobile applications.**\n\nTriggered by user actions or user segments, Formbricks gathers customer feedback, NPS scores, and churn insights directly into existing data pipelines without intrusive popups.', array[E'SMB operators', E'sales teams', E'commerce developers', E'open-source founders'], 'medium', 'published', 'verified', 'imported', true, E'Economics & Commerce', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
