insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000059', E'cs-prob-drift-protocol', E'Users lack a reliable way to: high-performance decentralized perpetual futures and cross-margined trading exchange', E'If unsolved, the status quo keeps hurting users: drift Protocol Drift emerged from early Solana hackathons into a premier decentralized derivatives exchange. Featuring dynamic automated market makers (DAMMs) coupled with decentralized limit order books, Drift delivers sub-second order fills, cross-margin lending, and b', E'If unsolved, the status quo keeps hurting users: drift Protocol Drift emerged from early Solana hackathons into a premier decentralized derivatives exchange. Featuring dynamic automated market makers (DAMMs) coupled with decentralized limit order books, Drift delivers sub-second order fills, cross-margin lending, and b\n\n## Drift Protocol\n\n**Drift emerged from early Solana hackathons into a premier decentralized derivatives exchange.**\n\nFeaturing dynamic automated market makers (DAMMs) coupled with decentralized limit order books, Drift delivers sub-second order fills, cross-margin lending, and borrow vaults with institutional security.', array[E'Solana ecosystem builders', E'DeFi traders', E'DAO treasurers', E'crypto power users', E'protocol developers'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
