insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000062', E'cs-prob-klimadao-protocol', E'Users lack a reliable way to: on-chain carbon market infrastructure accelerating climate action through tokenized carbon', E'If unsolved, the status quo keeps hurting users: klimaDAO KlimaDAO created a transparent on-chain carbon market to drive planetary environmental finance. KlimaDAO bridges real-world certified carbon offsets on-chain, creating a transparent liquid market that incentivizes conservation and enables businesses to offset em', E'If unsolved, the status quo keeps hurting users: klimaDAO KlimaDAO created a transparent on-chain carbon market to drive planetary environmental finance. KlimaDAO bridges real-world certified carbon offsets on-chain, creating a transparent liquid market that incentivizes conservation and enables businesses to offset em\n\n## KlimaDAO\n\n**KlimaDAO created a transparent on-chain carbon market to drive planetary environmental finance.**\n\nKlimaDAO bridges real-world certified carbon offsets on-chain, creating a transparent liquid market that incentivizes conservation and enables businesses to offset emissions programmatically via APIs.', array[E'DAO multisig signers', E'homeowners with solar/EV', E'climate startups', E'municipal sustainability teams', E'energy-conscious households'], 'medium', 'published', 'verified', 'imported', true, E'Climate & Sustainability', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
