insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000063', E'cs-prob-aquasave-network', E'People struggle to get smart ultrasonic water metering IoT and predictive leak detection when they need it for m', E'If unsolved, the status quo keeps hurting users: aquaSave Network Climate Award Winner @ Solana Renaissance Hackathon by Colosseum. AquaSave connects ultrasonic acoustic flow sensors across city municipal water pipes and residential meters via LoRaWAN, pinpointing underground pipe bursts in real time and saving million', E'If unsolved, the status quo keeps hurting users: aquaSave Network Climate Award Winner @ Solana Renaissance Hackathon by Colosseum. AquaSave connects ultrasonic acoustic flow sensors across city municipal water pipes and residential meters via LoRaWAN, pinpointing underground pipe bursts in real time and saving million\n\n## AquaSave Network\n\n**Climate Award Winner @ Solana Renaissance Hackathon by Colosseum.**\n\nAquaSave connects ultrasonic acoustic flow sensors across city municipal water pipes and residential meters via LoRaWAN, pinpointing underground pipe bursts in real time and saving millions of gallons of clean water.', array[E'Solana ecosystem builders', E'homeowners with solar/EV', E'climate startups', E'municipal sustainability teams', E'energy-conscious households'], 'medium', 'published', 'verified', 'imported', true, E'Climate & Sustainability', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
