insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000064', E'cs-prob-carekaki-voice-assistant', E'Isolated seniors lack warm daily check-ins that also surface care risks', E'Without gentle, consistent outreach, families miss early signs of missed meds, poor meals, or declining mood until a crisis hits.', E'Without gentle, consistent outreach, families miss early signs of missed meds, poor meals, or declining mood until a crisis hits.\n\n## CareKaki Voice Companion\n\n**Award-winning healthcare AI companion helping elderly seniors feel supported.**\n\nPlaces gentle, natural daily phone calls to chat with seniors about their day, meals, mood, and sleep, gently verifying medication routines and alerting caregivers if subtle health decline is detected.', array[E'family caregivers', E'isolated seniors', E'patients and caregivers', E'clinicians', E'healthtech builders'], 'medium', 'published', 'verified', 'imported', true, E'Healthcare & Medtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
