insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000065', E'cs-prob-starpower-energy', E'Users lack a reliable way to: global decentralized virtual power plant connecting residential air conditioners and batte', E'If unsolved, the status quo keeps hurting users: starpower Energy 3rd Prize in DePIN @ Solana Renaissance Hackathon by Colosseum. Starpower connects home smart plugs, air conditioners, and batteries into a global virtual power plant (VPP).', E'If unsolved, the status quo keeps hurting users: starpower Energy 3rd Prize in DePIN @ Solana Renaissance Hackathon by Colosseum. Starpower connects home smart plugs, air conditioners, and batteries into a global virtual power plant (VPP).\n\n## Starpower Energy\n\n**3rd Prize in DePIN @ Solana Renaissance Hackathon by Colosseum.**\n\nStarpower connects home smart plugs, air conditioners, and batteries into a global virtual power plant (VPP). During peak electricity surges, it coordinates micro-reductions in power draw across thousands of homes, preventing blackouts.', array[E'Solana ecosystem builders', E'homeowners with solar/EV', E'climate startups', E'municipal sustainability teams', E'energy-conscious households'], 'medium', 'published', 'verified', 'imported', true, E'Climate & Sustainability', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
