insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000066', E'cs-prob-detask-labor-dao', E'Users lack a reliable way to: aI-enabled decentralized software development and automated micro-bounty colation', E'If unsolved, the status quo keeps hurting users: deTask Labor 1st Prize Winner in DAOs & Communities @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC). DeTask coordinates open-source contributors and distributed developer DAOs.', E'If unsolved, the status quo keeps hurting users: deTask Labor 1st Prize Winner in DAOs & Communities @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC). DeTask coordinates open-source contributors and distributed developer DAOs.\n\n## DeTask Labor\n\n**1st Prize Winner in DAOs & Communities @ Solana Renaissance Hackathon by Colosseum ($30,000 USDC).**\n\nDeTask coordinates open-source contributors and distributed developer DAOs. Product managers submit high-level requirements, and DeTask''s AI breaks them down into well-scoped micro-tasks with automated smart contract escrow payouts.', array[E'DAO multisig signers', E'Solana ecosystem builders', E'community managers', E'civic technologists', E'self-hosting advocates'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
