insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000067', E'cs-prob-dialect-blinks', E'Users lack a reliable way to: smart messaging protocol and interactive blockchain action links (Solana )', E'If unsolved, the status quo keeps hurting users: dialect Dialect won early Solana hackathon acclaim and pioneered ''Blinks'' (Blockchain Links). Dialect turns any Solana transaction—swaps, votes, mints, donations—into an unfurlable interactive UI card that can be shared and executed directly inside Twitter/X, Discord, an', E'If unsolved, the status quo keeps hurting users: dialect Dialect won early Solana hackathon acclaim and pioneered ''Blinks'' (Blockchain Links). Dialect turns any Solana transaction—swaps, votes, mints, donations—into an unfurlable interactive UI card that can be shared and executed directly inside Twitter/X, Discord, an\n\n## Dialect\n\n**Dialect won early Solana hackathon acclaim and pioneered ''Blinks'' (Blockchain Links).**\n\nDialect turns any Solana transaction—swaps, votes, mints, donations—into an unfurlable interactive UI card that can be shared and executed directly inside Twitter/X, Discord, and Telegram messages.', array[E'Solana ecosystem builders', E'smart-contract developers', E'dApp product teams', E'DAO operators', E'wallet users'], 'medium', 'published', 'verified', 'imported', true, E'Blockchain & Web3', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
