insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000073', E'cs-prob-hospitalrun', E'Lack of open, self-hostable hospital management and patient records software designed for developing world clinics', E'If unsolved, the status quo keeps hurting users: hospitalRun HospitalRun makes healthcare software accessible to rural clinics in developing nations. Built with an offline-first architecture, HospitalRun enables doctors and nurses in remote regions with unstable electricity and internet to manage patient charts, pharma', E'If unsolved, the status quo keeps hurting users: hospitalRun HospitalRun makes healthcare software accessible to rural clinics in developing nations. Built with an offline-first architecture, HospitalRun enables doctors and nurses in remote regions with unstable electricity and internet to manage patient charts, pharma\n\n## HospitalRun\n\n**HospitalRun makes healthcare software accessible to rural clinics in developing nations.**\n\nBuilt with an offline-first architecture, HospitalRun enables doctors and nurses in remote regions with unstable electricity and internet to manage patient charts, pharmacy inventory, and surgical queues.', array[E'users in low-connectivity regions', E'patients and caregivers', E'clinicians', E'healthtech builders', E'elderly-care families'], 'medium', 'published', 'verified', 'imported', true, E'Healthcare & Medtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
