insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000075', E'cs-prob-svachsakthi-depin', E'People struggle to get off-grid cooperative network when they need it for decentralized renewable solar microgrids', E'If unsolved, the status quo keeps hurting users: svachSakthi Network 1st Prize in DePIN @ Solana Radar Hackathon by Colosseum ($30,000 USDC). Empowers rural off-grid villages to deploy community-owned solar power microgrids.', E'If unsolved, the status quo keeps hurting users: svachSakthi Network 1st Prize in DePIN @ Solana Radar Hackathon by Colosseum ($30,000 USDC). Empowers rural off-grid villages to deploy community-owned solar power microgrids.\n\n## SvachSakthi Network\n\n**1st Prize in DePIN @ Solana Radar Hackathon by Colosseum ($30,000 USDC).**\n\nEmpowers rural off-grid villages to deploy community-owned solar power microgrids. Smart meters log solar generation on-chain, enabling villagers to buy, sell, and share renewable energy via local mobile micropayments.', array[E'Solana ecosystem builders', E'homeowners with solar/EV', E'climate startups', E'municipal sustainability teams', E'energy-conscious households'], 'medium', 'published', 'verified', 'imported', true, E'Climate & Sustainability', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
