insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000076', E'cs-prob-staylock', E'Users lack a reliable way to: automating Trust between Travelers and Hosts', E'If unsolved, the status quo keeps hurting users: the project is a travel decentralized application (dApp) functioning as an intermediary platform between travelers and accommodation partners such as homestays or hotels. The system utilizes smart contracts to automatically handle processes such as deposits, cancellation', E'If unsolved, the status quo keeps hurting users: the project is a travel decentralized application (dApp) functioning as an intermediary platform between travelers and accommodation partners such as homestays or hotels. The system utilizes smart contracts to automatically handle processes such as deposits, cancellation\n\nThe project is a travel decentralized application (dApp) functioning as an intermediary platform between travelers and accommodation partners such as homestays or hotels. The system utilizes smart contracts to automatically handle processes such as deposits, cancellation policies, refunds, payment disbursements to partners upon completion of the stay, and customer reward point accumulation.', array[E'backpackers and solo travelers', E'tour operators', E'privacy-conscious tourists', E'navigation app users'], 'medium', 'published', 'verified', 'imported', true, E'Travel & Tourism', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
