insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000077', E'cs-prob-udonfi', E'Borrowers and lenders lack accessible collateral-backed P2P credit on open networks', E'If unsolved, local users stay dependent on opaque intermediaries or fragmented DeFi UX, while student builders lack a concrete Stellar lending reference path.', E'If unsolved, local users stay dependent on opaque intermediaries or fragmented DeFi UX, while student builders lack a concrete Stellar lending reference path.\n\nThe project is a decentralized peer-to-peer (P2P) lending platform built on the Stellar network and Soroban smart contracts, implementing the UdonFi model to enable direct, collateral-backed borrowing and lending for users.', array[E'Stellar/Soroban developers', E'Vietnam student builders (Da Nang / VNUK)', E'P2P lending experimenters', E'Crypto users seeking collateralized loans'], 'medium', 'published', 'verified', 'imported', true, E'Finance & DeFi', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
