insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000094', E'cs-prob-ev-share-driveway', E'People struggle to get community EV charger sharing network unlocking residential s when they need it for public', E'If unsolved, the status quo keeps hurting users: eV-Share Hub Unlocks thousands of private Level-2 residential EV chargers for public use. Homeowners list their driveway chargers when away at work.', E'If unsolved, the status quo keeps hurting users: eV-Share Hub Unlocks thousands of private Level-2 residential EV chargers for public use. Homeowners list their driveway chargers when away at work.\n\n## EV-Share Hub\n\n**Unlocks thousands of private Level-2 residential EV chargers for public use.**\n\nHomeowners list their driveway chargers when away at work. EV drivers find nearby residential chargers on the app, reserve time slots, and pay per kilowatt-hour, expanding EV charging access in dense cities.', array[E'homeowners with solar/EV', E'climate startups', E'municipal sustainability teams', E'energy-conscious households'], 'medium', 'published', 'verified', 'imported', true, E'Climate & Sustainability', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
