insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000096', E'cs-prob-skillbridge-verifiable', E'Centralized intermediaries dominate hands-on technical skill credentialing backed by GitHub PR contributions', E'If unsolved, the status quo keeps hurting users: skillBridge Verifiable Bridges the gap between self-taught programmers and tech recruiters. Instead of trusting superficial multiple-choice certificates, SkillBridge evaluates candidate code commits, merged open-source PRs, and code review rigor, issuing cryptographicall', E'If unsolved, the status quo keeps hurting users: skillBridge Verifiable Bridges the gap between self-taught programmers and tech recruiters. Instead of trusting superficial multiple-choice certificates, SkillBridge evaluates candidate code commits, merged open-source PRs, and code review rigor, issuing cryptographicall\n\n## SkillBridge Verifiable\n\n**Bridges the gap between self-taught programmers and tech recruiters.**\n\nInstead of trusting superficial multiple-choice certificates, SkillBridge evaluates candidate code commits, merged open-source PRs, and code review rigor, issuing cryptographically signed, verifiable competency badges.', array[E'students and teachers', E'university researchers', E'edtech builders', E'self-learners'], 'medium', 'published', 'verified', 'imported', true, E'Education & Edtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
