insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000097', E'cs-prob-civicvoice-portal', E'Citizens cannot follow opaque municipal hearings', E'If unsolved, the status quo keeps hurting users: civicVoice Local SIH Winning Civic Governance Platform: Makes local government transparent for citizens. Automatically transcribes municipal city council hearings, extracts proposed zoning changes and tax ordinances, summarizes neighborhood impacts in plain language, and', E'If unsolved, the status quo keeps hurting users: civicVoice Local SIH Winning Civic Governance Platform: Makes local government transparent for citizens. Automatically transcribes municipal city council hearings, extracts proposed zoning changes and tax ordinances, summarizes neighborhood impacts in plain language, and\n\n## CivicVoice Local\n\n**SIH Winning Civic Governance Platform: Makes local government transparent for citizens.**\n\nAutomatically transcribes municipal city council hearings, extracts proposed zoning changes and tax ordinances, summarizes neighborhood impacts in plain language, and tallies verified resident feedback for elected officials.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
