insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000098', E'cs-prob-disasterrelief-mesh', E'Disaster zones lose communication when towers fail', E'If unsolved, the status quo keeps hurting users: disasterRelief Mesh Winner @ GOOD Hackathon: Saves lives when natural disasters knock out cellular towers. Using Bluetooth and Wi-Fi Direct peer-to-peer mesh networking, stranded victims broadcast SOS emergency medical requests, GPS coordinates, and supply needs directly', E'If unsolved, the status quo keeps hurting users: disasterRelief Mesh Winner @ GOOD Hackathon: Saves lives when natural disasters knock out cellular towers. Using Bluetooth and Wi-Fi Direct peer-to-peer mesh networking, stranded victims broadcast SOS emergency medical requests, GPS coordinates, and supply needs directly\n\n## DisasterRelief Mesh\n\n**Winner @ GOOD Hackathon: Saves lives when natural disasters knock out cellular towers.**\n\nUsing Bluetooth and Wi-Fi Direct peer-to-peer mesh networking, stranded victims broadcast SOS emergency medical requests, GPS coordinates, and supply needs directly to rescue squads across multi-hop phone relays without cellular signal.', array[E'community managers', E'civic technologists', E'self-hosting advocates', E'public-sector IT teams'], 'medium', 'published', 'verified', 'imported', true, E'Social & Civic Tech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
