insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000100', E'cs-prob-luggagehop-p2p', E'Centralized intermediaries dominate luggage storage network connecting travelers with verified boutique cafes and shops', E'If unsolved, the status quo keeps hurting users: luggageHop P2P Eliminates dragging heavy suitcases around tourist destinations before hotel check-in. Connects travelers with vetted cafes, dry cleaners, and hotels to store luggage safely by the hour with tamper-evident QR seals and included insurance protection.', E'If unsolved, the status quo keeps hurting users: luggageHop P2P Eliminates dragging heavy suitcases around tourist destinations before hotel check-in. Connects travelers with vetted cafes, dry cleaners, and hotels to store luggage safely by the hour with tamper-evident QR seals and included insurance protection.\n\n## LuggageHop P2P\n\n**Eliminates dragging heavy suitcases around tourist destinations before hotel check-in.**\n\nConnects travelers with vetted cafes, dry cleaners, and hotels to store luggage safely by the hour with tamper-evident QR seals and included insurance protection.', array[E'backpackers and solo travelers', E'tour operators', E'privacy-conscious tourists', E'navigation app users'], 'medium', 'published', 'verified', 'imported', true, E'Travel & Tourism', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
