insert into public.problems (id, slug, title, summary, description, affected_groups, severity, status, research_status, origin, reviewed_by_human, industry, created_by) values (E'30000000-0000-4000-9000-000000000101', E'cs-prob-vitalsync-iot-telemetry', E'Users lack a reliable way to: remote patient hub predicting cardiac and respiratory deterioration events', E'If unsolved, the status quo keeps hurting users: vitalSync IoT Enables proactive remote patient monitoring for chronic cardiac and COPD patients. Aggregates Bluetooth telemetry from pulse oximeters, blood pressure cuffs, and ECG patches.', E'If unsolved, the status quo keeps hurting users: vitalSync IoT Enables proactive remote patient monitoring for chronic cardiac and COPD patients. Aggregates Bluetooth telemetry from pulse oximeters, blood pressure cuffs, and ECG patches.\n\n## VitalSync IoT\n\n**Enables proactive remote patient monitoring for chronic cardiac and COPD patients.**\n\nAggregates Bluetooth telemetry from pulse oximeters, blood pressure cuffs, and ECG patches. Machine learning models detect decompensation patterns 48 hours before clinical hospitalization is required.', array[E'patients and caregivers', E'clinicians', E'healthtech builders', E'elderly-care families'], 'medium', 'published', 'verified', 'imported', true, E'Healthcare & Medtech', E'10000000-0000-4000-8000-000000000099') on conflict (slug) do nothing;
